fn clone_vec(b: &Vec<f64>) -> Vec<f64> {
    // Simply clone all entries of b
    b.iter().cloned().collect()
}

fn solve(a: Vec<Vec<f64>>, b: Vec<f64>) -> Vec<f64> {
    let n = a.len();
    // Build the augmented matrix m of size n × (n+1)
    let mut m = a;
    for i in 0..n {
        m[i].push(b[i]);
    }

    // Forward elimination with partial pivoting
    for i in 0..n {
        // 1) Find pivot row (max absolute value in column i)
        let mut max_row = i;
        let mut max_val = m[i][i].abs();
        for k in (i + 1)..n {
            let val = m[k][i].abs();
            if val > max_val {
                max_val = val;
                max_row = k;
            }
        }
        // 2) Swap current row with pivot row
        if max_row != i {
            m.swap(i, max_row);
        }
        // 3) Eliminate rows below
        let pivot = m[i][i];
        for j in (i + 1)..n {
            let factor = m[j][i] / pivot;
            for k in i..=n {
                m[j][k] -= factor * m[i][k];
            }
        }
    }

    // Back substitution
    let mut x = vec![0.0; n];
    for i in (0..n).rev() {
        let mut sum = m[i][n];
        for j in (i + 1)..n {
            sum -= m[i][j] * x[j];
        }
        x[i] = sum / m[i][i];
    }

    x
}

// Example usage
fn main() {
    let a = vec![
        vec![2.0, 1.0, -1.0],
        vec![-3.0, -1.0, 2.0],
        vec![-2.0, 1.0, 2.0],
    ];
    let b = vec![8.0, -11.0, -3.0];
    let x = solve(a, b);
    println!("{:?}", x); // should print [2.0, 3.0, -1.0]
}